// Series data — Attribution.
// Generated by generate.js from results.csv: task "attribution"
// (spiral, ascii8, sensitive), budget 2^48 per search. One record
// per edge; its steps are every successively longer prefix match (first
// counter value per match length) of the one continuing grind. Every
// candidate message is base ‖ counter (64-bit little-endian; the counter is
// the "nonce" column in results.csv); every hash below was re-verified as
// SHA-256(base ‖ counter) at generation time.
(function () {
  const grinding = window.grinding = window.grinding || {};

  // base, word, matched chars, counter (the csv’s nonce), hash
  const rows = [
    ["artist", "rhea", 2, 588904, "72686e44983b96ee4d6adeafead282d3655791c00dbe4ff13e1198500e2afe97"],
    ["artist", "rhea", 3, 31696758, "726865d93d00f443efd24d8cb31394cee70f99670e209c847cd9c4066cb4c43d"],
    ["artist", "rhea", 4, 10044337458, "726865618a051b78226c662099e54ab71c8b110d50f459ae589eb0957a033ab7"],
    ["artist", "myers", 3, 172765, "6d796503c374694fd995720b419a02f256b0b3aeb83dda71e36808d4cbeebe7e"],
    ["artist", "myers", 4, 3624417777, "6d796572185eafd685ed127277f560ef49174e6c2796447db0830d5eebe0fb74"],
    ["artist", "myers", 5, 503097329244, "6d7965727365f978718076fa3b92e4fed8f221252fe5aa908cdc444e58e8a329"],
  ];

  // every-hit collection: word -> [full hits kept, deepest winning counter]
  const hits = {
    "rhea": [15743, 68125576480628],
    "myers": [5, 3984451688103],
  };

  const ascii8hex = s => [...s].map(c => c.charCodeAt(0).toString(16).padStart(2, "0")).join("");
  const edges = [];
  for (const [base, word] of rows)
    if (!edges.some(e => e[0] === base && e[1] === word)) edges.push([base, word]);

  grinding.series = {
    name: "Attribution",
    slug: "attribution",
    base: "artist",
    topology: "spiral",
    searchEncoding: "ascii8",
    caseMode: "sensitive",
    hashFunction: "SHA-256",
    budgetBits: 48,
    tokenId: 12, // position in the fixed edition; scripts/tokens.js agrees
    records: edges.map(([base, word], index) => {
      let prevNonce = 0;
      const steps = rows.filter(r => r[0] === base && r[1] === word)
        .map(([, , matchedChars, nonce, hash]) => {
          const st = { matchedChars, nonce, prevNonce, deltaAttempts: nonce - prevNonce, hash };
          prevNonce = nonce;
          return st;
        });
      const final = steps[steps.length - 1];
      return {
        index,
        word,
        base,
        plaintext: word, // as it appears in the csv
        totalChars: word.length,
        matchedChars: final.matchedChars, // < totalChars if the budget ran out
        full: final.matchedChars === word.length,
        encodedHex: ascii8hex(word),
        matchedNibbles: final.matchedChars * 2,
        nonce: final.nonce,
        attempts: final.nonce + 1,
        hash: final.hash,
        steps,
        hits: (hits[word] || [])[0], // undefined on the return searches
        lastNonce: (hits[word] || [])[1]
      };
    }),
    words: ["rhea","myers"]
  };
})();
